    wire host_256b_aw_to_desc_ram = ((host_256b_aw.addr >= 32'h00020000) && (host_256b_aw.addr <= 32'h0002ffff));
    wire host_256b_ar_to_desc_ram = ((host_256b_ar.addr >= 32'h00020000) && (host_256b_ar.addr <= 32'h0002ffff));
