    assign desc_ram_axi_awid = (host_256b_aw_gnt_desc_ram ? host_256b_aw.id : '0);
    assign desc_ram_axi_awaddr = (host_256b_aw_gnt_desc_ram ? host_256b_aw.addr : '0);
